def update(self, kwargs):
    # docstring inherited
    # Update font properties before updating other kwargs, so that size can be properly set.
    sentinel = object()  # bbox can be None, so use another sentinel.
    bbox = kwargs.pop("bbox", sentinel)

    # Handle font properties correctly to ensure size is considered correctly
    font_properties = {k: kwargs.pop(k) for k in ['fontsize', 'fontproperties'] if k in kwargs}

    if 'fontsize' in font_properties:
        self.set_fontsize(font_properties['fontsize'])
    if 'fontproperties' in font_properties:
        self.set_font_properties(font_properties['fontproperties'])

    super().update(kwargs)

    if bbox is not sentinel:
        self.set_bbox(bbox)
